//! Native RCDATA replacement shares the admitted textarea default transaction.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document_with_scripting("<body><form id=form><textarea id=area name=q>Held</textarea><input id=neighbor value=seed></form><p id=out>Real</p>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://textarea-inner.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->String{let source=format!("var failure=null;try{{{s}}}catch(e){{failure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let Value::String(e)=p.runtime.execute("failure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()else{panic!("Expected refusal: {s}")};e}}}
fn area(d:&Document,f:&Forms)->usize{*f.controls.keys().find(|&&n|d.attr(n,"id")==Some("area")).unwrap()}
#[test]
fn textarea_inner_html_rcdata_pristine_native_defaults_and_preprocessing_order(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var x=document.getElementById('area'),old=x.firstChild,raw='A\r\n&#13;&amp;&NotEqualTilde;&Afr;&#xD800;\0&lt;img id=fake src=missing&gt;&amp;lt;',expected='A\n\r&\u2242\u0338\ud835\udd04\ufffd\ufffd<img id=fake src=missing>&lt;';x.innerHTML=raw;if(x.firstChild===old||old.parentNode!==null||old.data!=='Held'||x.firstChild.data!==expected||x.defaultValue!==expected||x.textContent!==expected||x.value!==expected.replace('\r','\n')||x.firstChild.data.charCodeAt(2)!==13||document.getElementById('fake')!==null||document.getElementById('neighbor').value!=='seed')throw 'native pristine RCDATA defaults';var clone=x.cloneNode(true);if(clone===x||clone.firstChild===x.firstChild||clone.defaultValue!==expected||clone.value!==x.value||clone.ownerDocument!==document)throw 'independent native parsed default clone';
"#);assert!(!f.controls[&area(&d,&f)].dirty_value);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn textarea_inner_html_rcdata_dirty_editor_author_conversion_and_actual_reset(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),calls=0;x.value='kept edit';");let n=area(&d,&f);{let e=&mut f.controls.get_mut(&n).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}
 run(&mut d,&mut f,&mut p,r#"x.innerHTML={toString:function(){calls++;return 'New\r\n&#13;&amp;&Afr;';}};if(calls!==1||x.defaultValue!=='New\n\r&\ud835\udd04'||x.value!=='kept edit')throw 'native dirty RCDATA conversion';"#);
 let c=&f.controls[&n];assert_eq!((c.value.text(),c.value.cursor,c.value.anchor,c.value.offset),("kept edit".into(),5,2,1));assert!(c.dirty_value);let owner=c.owner.unwrap();f.reset_in_document(&d,owner).unwrap();p.begin_job();run(&mut d,&mut f,&mut p,r#"if(x.value!=='New\n\n&\ud835\udd04'||x.defaultValue!=='New\n\r&\ud835\udd04')throw 'actual native reset uses parsed default';"#);assert!(!f.controls[&n].dirty_value);
}
#[test]
fn textarea_inner_html_rcdata_native_records_ranges_iterator_clear_and_recovery(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var x=document.getElementById('area'),old=x.firstChild,r=document.createRange(),it=document.createNodeIterator(x,4),watch=new MutationObserver(function(){});r.setStart(old,1);r.setEnd(old,3);if(it.nextNode()!==old)throw 'actual iterator setup';watch.observe(x,{childList:true,characterData:true,subtree:true});x.innerHTML='&lt;b&gt;&amp;';var text=x.firstChild,records=watch.takeRecords();if(text.data!=='<b>&'||text.ownerDocument!==document||text.parentNode!==x||old.parentNode!==null||old.data!=='Held'||r.startContainer!==x||r.startOffset!==0||r.endContainer!==x||r.endOffset!==0||it.nextNode()!==text||records.length!==1||records[0].target!==x||records[0].removedNodes[0]!==old||records[0].addedNodes[0]!==text||x.innerHTML!=='&lt;b&gt;&amp;'||x.value!=='<b>&')throw 'native parsed default records and boundaries';x.innerHTML='';records=watch.takeRecords();if(x.firstChild!==null||x.defaultValue!==''||x.value!==''||text.parentNode!==null||text.data!=='<b>&'||records.length!==1||records[0].removedNodes[0]!==text||records[0].addedNodes.length)throw 'native parsed empty default';x.innerHTML='Fresh&amp;';records=watch.takeRecords();if(x.defaultValue!=='Fresh&'||x.value!=='Fresh&'||records.length!==1||records[0].addedNodes[0]!==x.firstChild)throw 'fresh parsed default';
"#);
}
#[test]
fn textarea_inner_html_rcdata_resource_quota_refusals_preserve_defaults_then_recover(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),old=x.firstChild,watch=new MutationObserver(function(){});watch.observe(x,{childList:true,characterData:true,subtree:true});x.value='dirty';");p.state.rebuild(&d).unwrap();let n=area(&d,&f);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let retained=p.state.retained_limit;let nodes=p.state.node_limit;let strings=p.state.limits.host.string_bytes;
 for mode in 0..6{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),4=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=refusal(&mut d,&mut f,&mut p,"x.innerHTML='New&#13;&amp;';").to_ascii_lowercase();assert!(e.contains("limit")||e.contains("allowance")||e.contains("storage"),"{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);assert_eq!(f.controls[&n].value.text(),"dirty");assert!(f.controls[&n].dirty_value);p.state.retained_limit=retained;p.state.node_limit=nodes;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;}
 p.begin_job();p.state.limits.host.string_bytes=3;let e=refusal(&mut d,&mut f,&mut p,"x.innerHTML='\\0\\0';");assert!(e.contains("Decoded textarea output"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);assert_eq!(f.controls[&n].value.text(),"dirty");p.state.limits.host.string_bytes=strings;
 p.begin_job();assert!(!refusal(&mut d,&mut f,&mut p,"x.innerHTML='\\udfff\\ud800&amp;';").is_empty());assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(x.firstChild!==old||x.defaultValue!=='Held'||x.value!=='dirty'||watch.takeRecords().length)throw 'no native default prefix';x.innerHTML='Recovered&amp;';if(x.defaultValue!=='Recovered&'||x.value!=='dirty'||watch.takeRecords().length!==1)throw 'fresh native default recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
